 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The task is made of several independent horizontal bars and vertical
    # marker rays. For each isolated nonzero cell below a bar, find the
    # horizontal bar of that cell's color and extend the ray through its gap.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            # Only isolated pixels start the vertical ray; skip cells that
            # belong to horizontal bars or have a same-color neighbor above.
            if (c > 0 and grid[r][c-1] == color) or (c + 1 < w and grid[r][c+1] == color):
                continue
            if r > 0 and grid[r-1][c] == color:
                continue
            # Track downward extent of this vertical marker.
            end = r
            while end + 1 < h and grid[end+1][c] == color:
                end += 1
            # Search upward for the nearest horizontal bar of this color;
            # connect from the bar's missing gap to this vertical marker.
            for br in range(r - 1, -1, -1):
                row = grid[br]
                if any(v != 0 and v != color for v in row):
                    continue
                for gc in range(1, w - 1):
                    if row[gc] == 0 and row[gc-1] == color and row[gc+1] == color:
                        for rr in range(br + 1):
                            out[rr][gc] = color
                        break
    return out
