    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bars = {}
    for r, row in enumerate(grid):
        for c in range(1, w-1):
            if row[c] == 0 and row[c-1] != 0 and row[c+1] == row[c-1]:
                bars.setdefault(c, []).append((r, row[c-1]))
    # Gaps are crossings: fill them, then draw each vertical line upward.
    # Every segment above a crossing takes the color of that crossing.
    for c, crossings in bars.items():
        crossings.sort()
        for r, color in crossings:
            out[r][c] = color
        # Before the highest crossing use that crossbar's color.
        r0, color0 = crossings[0]
        for rr in range(r0):
            out[rr][c] = color0
        # From each crossing upward to the one above, use lower crossing color.
        for i in range(1, len(crossings)):
            upper_r = crossings[i-1][0]
            r, color = crossings[i]
            for rr in range(upper_r+1, r):
                out[rr][c] = color
    return out
