                tracks.setdefault(c, []).append((r, color))
    # Complete broken horizontal bars and draw their vertical stems upward.
    for c, marks in tracks.items():
        marks.sort()
        start = 0
        for r, color in marks:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1
    # Bottom endpoint markers are at least three cells tall; extend short
    # vertical seeds upward, without changing their existing cells.
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] != 0]
        if rs and rs[-1] == h - 1 and len(rs) == h - rs[0]:
            color = grid[h - 1][c]
            top = min(rs)
            for r in range(max(0, h - 3), top):
                out[r][c] = color
    return out
