{
 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Every broken bar is repaired, and a vertical line extends from each
    # break upward. The line switches to the next bar's color above crossings.
    bycol={}
    for r,row in enumerate(grid):
        for c in range(1,w-1):
            col=row[c-1]
            if col and row[c]==0 and row[c+1]==col:
                bycol.setdefault(c,[]).append((r,col))
    for c,items in bycol.items():
        items.sort()
        for r,col in items: out[r][c]=col
        # Fill upward from each bar to the next bar above; top section uses
        # the highest bar's color. Segment just above a bar inherits that bar.
        for i,(r,col) in enumerate(items):
            upper=items[i-1][0] if i else 0
            for rr in range(upper+1,r): out[rr][c]=col
        # Existing bottom vertical marker continues upward until first crossing.
        lower=items[-1][0]
        if any(grid[rr][c] for rr in range(lower+1,h)):
            marker=next(grid[rr][c] for rr in range(h-1,lower,-1) if grid[rr][c])
            for rr in range(lower+1,h): out[rr][c]=marker
    return out
