            color = row[c - 1]
            if color and row[c] == 0 and row[c + 1] == color:
                tracks.setdefault(c, []).append((r, color))

    # Complete each bar and extend its vertical track upward. Each vertical
    # interval immediately above a crossing inherits that crossing's color.
    for c, crossings in tracks.items():
        crossings.sort()
        start = 0
        for r, color in crossings:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1

    # Extend any vertical marker ending at the bottom to at least three cells.
    for c in range(w):
        if grid[h - 1][c] == 0:
            continue
        color = grid[h - 1][c]
        length = 0
        r = h - 1
        while r >= 0 and grid[r][c] == color:
            length += 1
            r -= 1
        for rr in range(max(0, h - 3), h - length):
            out[rr][c] = color

